# Writes src/FaceGeometry.h from assets/geometry.json (key and LCD rectangles measured on the face pictures).
# Run from anywhere:  python3 tools/gen_face_geometry.py
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
geo = json.load(open(os.path.join(ROOT, "assets", "geometry.json")))
out = ['// SPDX-License-Identifier: MIT', '// Copyright (c) 2026 José González Divassón',
       '//', '// FaceGeometry.h - GENERATED by tools/gen_face_geometry.py from assets/geometry.json; do not edit.',
       '// Key and LCD rectangles on the photo faces, as fractions of the face (x, y, w, h; origin top-left).',
       '#pragma once', '', 'namespace vc {', '',
       'struct Rect4 { double x, y, w, h; };',
       'struct FaceGeometry {', '    int model;', '    const char *image;     // Qt resource path of the face with the LCD glass emptied',
       '    int pixelW, pixelH;', '    Rect4 lcd;', '    bool hasKey[40];', '    Rect4 key[40];', '};', '']
for m in ("12c", "15c", "16c"):
    g = geo[m]
    w, h = g["size"]
    keys = {int(k): v for k, v in g["keys"].items()}
    out.append(f'inline const FaceGeometry kFace{m.upper()} = {{')
    out.append(f'    {int(m[:2])}, ":/faces/face_{m}_nolcd.png", {w}, {h},')
    out.append('    {%s},' % ", ".join(repr(float(x)) for x in g["lcd"]))
    out.append('    {%s},' % ", ".join("true" if i in keys else "false" for i in range(40)))
    out.append('    {')
    for i in range(40):
        r = keys.get(i, [0, 0, 0, 0])
        out.append('        {%s},' % ", ".join(repr(float(x)) for x in r))
    out.append('    }')
    out.append('};')
    out.append('')
out += ['}  // namespace vc', '']
open(os.path.join(ROOT, "src", "FaceGeometry.h"), "w").write("\n".join(out))
print("wrote src/FaceGeometry.h")
